import{_ as o,o as r,c as s,a3 as n}from"./chunks/framework.Cc-oPviL.js";const l="/study-hub/assets/K02_acf_pacf_quadrant.B8q8HHDI.png",d=JSON.parse('{"title":"第三章　线性模型族：AR、MA、ARMA","description":"","frontmatter":{},"headers":[],"relativePath":"timeseries/03.md","filePath":"timeseries/03.md"}'),e={name:"timeseries/03.md"};function a(p,t,g,A,u,q){return r(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="第三章-线性模型族-ar、ma、arma" tabindex="-1">第三章　线性模型族：AR、MA、ARMA <a class="header-anchor" href="#第三章-线性模型族-ar、ma、arma" aria-label="Permalink to &quot;第三章　线性模型族：AR、MA、ARMA&quot;">​</a></h1><p>本章是模型部分的地基：AR、MA、ARMA 三族的定义、平稳域与可逆域、ACF/PACF 的理论特征，以及把三者统一起来的 Green 函数表示。</p><h2 id="_3-1-移动平均模型-ma-q" tabindex="-1">3.1 移动平均模型 MA(q) <a class="header-anchor" href="#_3-1-移动平均模型-ma-q" aria-label="Permalink to &quot;3.1 移动平均模型 MA(q)&quot;">​</a></h2><blockquote><p>yₜ = μ + εₜ + θ₁εₜ₋₁ + … + θ_qεₜ₋q，　εₜ ~ WN(0, σ²)</p></blockquote><p><strong>平稳性</strong>：MA(q) 是有限个白噪声的线性组合，<strong>永远是平稳的</strong>（只要 θ 有限）。这一点与 AR 截然不同。</p><blockquote><p><strong>打个比方</strong>：MA 就是<strong>往水里扔石头</strong>。今天的水面高度（yₜ）＝ 今天扔的那块石头激起的水花（εₜ）＋ 前几块石头还没散尽的波纹（θ₁εₜ₋₁、θ₂εₜ₋₂ …）。</p><p>三个结论一眼就能看出来：</p><ul><li><strong>q 阶 = 一块石头最多影响 q 期</strong>，之后水面彻底平静。所以 ACF 在 k &gt; q 后严格为零——两块石头的波纹隔得太远，完全不重叠。</li><li><strong>永远平稳</strong>：石头只扔了有限块，波纹总会散完，不会越积越高。这就是为什么 MA 部分不影响平稳性。</li><li><strong>θ 是&quot;波纹残留的比例&quot;</strong>：θ 越大，这块石头的余波越持久。</li></ul></blockquote><p><strong>可逆性</strong>：若特征多项式</p><blockquote><p>1 + θ₁z + … + θ_qz^q = 0</p></blockquote><p>的<strong>所有根都在单位圆外</strong>，则 MA(q) 可逆——可以等价地写成 AR(∞) 形式。可逆性的实际意义是：给定观测数据，能够唯一地反推出 εₜ 的历史。不可逆的 MA 模型无法用于预测。</p><p><strong>自协方差</strong>：</p><blockquote><p>γ₀ = σ²(1 + θ₁² + … + θ_q²)<br> γₖ = σ²(θₖ + θₖ₊₁θ₁ + … + θ_qθ_q₋ₖ)，　1 ≤ k ≤ q<br> γₖ = 0，　k &gt; q</p></blockquote><p><strong>ACF</strong>：在 k &gt; q 后<strong>截尾</strong>（严格为零）。这是 MA 最鲜明的特征。</p><p><strong>PACF</strong>：拖尾（指数衰减或振荡衰减）。</p><h2 id="_3-2-自回归模型-ar-p" tabindex="-1">3.2 自回归模型 AR(p) <a class="header-anchor" href="#_3-2-自回归模型-ar-p" aria-label="Permalink to &quot;3.2 自回归模型 AR(p)&quot;">​</a></h2><blockquote><p>yₜ = c + φ₁yₜ₋₁ + … + φ_pyₜ₋p + εₜ</p></blockquote><blockquote><p><strong>打个比方</strong>：AR 就是<strong>回声</strong>，或者说是<strong>惯性</strong>。今天的值主要是&quot;昨天的值打个折&quot;，再叠一点新扰动；φ 就是这个折扣率。</p><p>三种情况一眼分明：</p><ul><li><strong>|φ| &lt; 1</strong>：每次回声都比上一次弱（0.9 → 0.81 → 0.73 …），最终消失——<strong>平稳</strong>。</li><li><strong>φ = 1</strong>：回声不打折，原封不动往下传——<strong>随机游走</strong>，方差越积越大。</li><li><strong>|φ| &gt; 1</strong>：回声一次比一次响，最后炸掉——<strong>爆炸</strong>，现实里不会长期存在。</li></ul><p>AR(2) 出现&quot;衰减振荡&quot;，是因为二阶系统有两个回声源在互相叠加，像钟摆左右摆着、越摆越小，最后停下。</p></blockquote><p><strong>平稳条件</strong>：特征方程</p><blockquote><p>1 − φ₁z − … − φ_pz^p = 0</p></blockquote><p>的所有根<strong>都在单位圆外</strong>。</p><p>低阶情形可以写成更直观的形式：</p><ul><li>AR(1)：|φ₁| &lt; 1</li><li>AR(2)：φ₁ + φ₂ &lt; 1，φ₂ − φ₁ &lt; 1，|φ₂| &lt; 1（这三个不等式围成三角形平稳域）</li></ul><p><strong>均值</strong>：</p><blockquote><p>E(y) = c / (1 − φ₁ − … − φ_p)</p></blockquote><p>注意分母是 1 减去全部自回归系数之和。当 Σφᵢ 接近 1 时，均值会被放大得很大——这也是&quot;接近单位根&quot;的另一种表现。</p><p><strong>ACF</strong>：拖尾。AR(1) 为 ρₖ = φ₁ᵏ 的指数衰减；AR(2) 在判别式为正时指数衰减，为负时呈衰减振荡。</p><p><strong>PACF</strong>：p 阶后<strong>截尾</strong>。</p><h2 id="_3-3-arma-p-q" tabindex="-1">3.3 ARMA(p, q) <a class="header-anchor" href="#_3-3-arma-p-q" aria-label="Permalink to &quot;3.3 ARMA(p, q)&quot;">​</a></h2><blockquote><p>yₜ = c + Σᵢ₌₁ᵖ φᵢyₜ₋ᵢ + εₜ + Σⱼ₌₁^q θⱼεₜ₋ⱼ</p></blockquote><blockquote><p><strong>打个比方</strong>：ARMA 就是<strong>被推的秋千</strong>。秋千自己有固有频率，你松手后它还会按自己的节奏晃一阵（AR 部分）；而推你的那只手也不是瞬间离开，掌心还留着一点余力（MA 部分）。两种效应叠在一起，就是 ARMA。</p><p>这条比喻正好解释了下面那条分工：<strong>秋千会不会越晃越大，只看它自己的固有频率</strong>——AR 决定平稳性；<strong>能不能从晃动轨迹反推出每一把推力</strong>——MA 决定可逆性。两件事互不干涉。</p></blockquote><p>★ <strong>一条必须记住的分工</strong>：</p><ul><li><strong>平稳性只由 AR 部分决定</strong>（MA 部分不影响平稳性，因为它是有限个白噪声的组合）；</li><li><strong>可逆性只由 MA 部分决定</strong>（AR 部分不影响可逆性）。</li></ul><p><strong>ACF 与 PACF 都拖尾</strong>，这是 ARMA 的识别特征，也是它难以定阶的原因。</p><p>★ <strong>参数冗余问题。</strong> ARMA(1,1) 中若 φ ≈ −θ，则 (1 − φB)yₜ = (1 + θB)εₜ 两边的多项式近似相等，可以约掉，模型实际退化为白噪声。此时系数估计值会很大、标准误更大、两者高度负相关。这是&quot;参数不可识别&quot;的典型表现，处理办法是降阶。</p><h2 id="_3-4-green-函数与-ma-∞-表示" tabindex="-1">3.4 Green 函数与 MA(∞) 表示 <a class="header-anchor" href="#_3-4-green-函数与-ma-∞-表示" aria-label="Permalink to &quot;3.4 Green 函数与 MA(∞) 表示&quot;">​</a></h2><p>任何平稳可逆的 ARMA 模型都可以写成无穷阶移动平均形式：</p><blockquote><p>yₜ = μ + Σⱼ₌₀^∞ ψⱼεₜ₋ⱼ，　ψ₀ = 1</p></blockquote><p>系数 ψⱼ 称为 <strong>Green 函数</strong>（也叫脉冲响应函数），它表示&quot;第 t−j 期的一个单位冲击对第 t 期的影响&quot;。它由 ARMA 算子之比展开得到：</p><blockquote><p><strong>打个比方</strong>：ψⱼ 就是<strong>涟漪在第 j 期还剩多高</strong>。往水里扔一块石头（一次单位冲击），水花当时最高（ψ₀ = 1），之后一期比一期低。整条 ψ₀, ψ₁, ψ₂, … 就是这次冲击的&quot;余波曲线&quot;。</p><p>曲线一画出来，很多事就直观了：<strong>衰减得快</strong> = 记性差，冲击很快过去；<strong>衰减得慢</strong> = 冲击会拖很久；<strong>完全不衰减</strong>（ψⱼ 恒为 1）= 随机游走，一次冲击永久改变水平。第八章的预测误差方差，本质就是把这条曲线上的值平方求和——余波越长，预测越没底。</p></blockquote><blockquote><p>ψ(B) = θ(B)/φ(B)</p></blockquote><p>以 ARMA(1,1) 为例，yₜ = φyₜ₋₁ + εₜ + θεₜ₋₁：</p><blockquote><p>ψ₀ = 1<br> ψ₁ = φ + θ<br> ψⱼ = φ^(j−1)(φ + θ)，　j ≥ 2</p></blockquote><p><strong>Green 函数的三个用途</strong>：</p><ol><li>算自协方差：γₖ = σ² Σⱼ₌₀^∞ ψⱼψⱼ₊ₖ</li><li>算预测误差方差（第八章）</li><li>判断冲击的持续性：ψⱼ 衰减越快，记忆越短</li></ol><h2 id="_3-5-平稳域与可逆域" tabindex="-1">3.5 平稳域与可逆域 <a class="header-anchor" href="#_3-5-平稳域与可逆域" aria-label="Permalink to &quot;3.5 平稳域与可逆域&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>由谁决定</th><th>条件</th><th>违反的后果</th></tr></thead><tbody><tr><td>平稳域</td><td>AR 部分</td><td>AR 特征根在单位圆外</td><td>序列非平稳，方差随时间增长，无法用 ARMA 描述</td></tr><tr><td>可逆域</td><td>MA 部分</td><td>MA 特征根在单位圆外</td><td>无法由数据反推 εₜ，预测不可行，且同一 ACF 对应多个 MA 模型</td></tr></tbody></table><p><strong>边界情况</strong>：根恰好落在单位圆上（模 = 1）即为单位根，既不平稳也不可逆。</p><blockquote><p><strong>打个比方</strong>：这两个&quot;域&quot;管的是两件完全不同的事，别混在一起记。</p><ul><li><strong>平稳域管&quot;会不会失控&quot;</strong>：序列自己会不会越走越散。根跑进圆内 = 回声越来越大 = 爆炸。</li><li><strong>可逆域管&quot;能不能倒推&quot;</strong>：能不能从看到的结果反推出当初的冲击。MA 不可逆，意味着<strong>好几组不同的 ε 能生成完全相同的 y</strong>，你分不清到底是哪一组——就像听到一段和声，却判断不出是三个人唱的，还是两个人唱出来的效果。</li></ul><p>一句话：<strong>一个管&quot;未来稳不稳&quot;，一个管&quot;过去能不能还原&quot;。</strong> 前者决定能不能建模，后者决定能不能预测。</p></blockquote><p>★ <strong>数值实现上的陷阱。</strong> 软件求根是浮点运算，&quot;根在单位圆外&quot;的判断需要一个阈值。实践中常见 MA 根 = 1.0000002 这种&quot;差一点点&quot;的情况——数学上它在圆外，统计上它等同于不可逆，此时模型的预测会极不稳定。合理的做法是设一个宽松边界（如要求最小根 ≥ 1.0001），把临界情况当作不可逆处理，并在结果中记录被剔除的原因。</p><blockquote><p><strong>打个比方</strong>：这就像<strong>门框量出来&quot;刚好能过&quot;</strong>——数学上宽了 0.0002 毫米，人走过去照样卡住。判据不能只看&quot;在不在圆外&quot;，要看&quot;离边界还有多远&quot;。所以实践里要设一个宽松门槛，把这种&quot;擦边过&quot;的模型直接当不可逆剔掉，而不是让它混进候选集。</p></blockquote><h2 id="_3-6-yule-walker-方程" tabindex="-1">3.6 Yule-Walker 方程 <a class="header-anchor" href="#_3-6-yule-walker-方程" aria-label="Permalink to &quot;3.6 Yule-Walker 方程&quot;">​</a></h2><p>对 AR(p)，两边同乘 yₜ₋ₖ 取期望并除以 γ₀，得到</p><blockquote><p>ρₖ = φ₁ρₖ₋₁ + φ₂ρₖ₋₂ + … + φ_pρₖ₋p，　k ≥ 1</p></blockquote><p>取 k = 1, 2, …, p，得到 p 个方程的线性方程组：</p><blockquote><p><strong>P</strong> φ = ρ</p></blockquote><p>其中 <strong>P</strong> 是 ρ 组成的 Toeplitz 矩阵。解出 φ 即得<strong>矩估计</strong>。</p><blockquote><p><strong>打个比方</strong>：这是<strong>根据听到的音色反推调音台旋钮</strong>。你听到的最终声音（ρ₁, ρ₂, … 这些自相关）是几个旋钮（φ₁, φ₂, …）组合出来的结果；Yule-Walker 就是那组&quot;把听到什么翻译成旋钮拧在几档&quot;的方程。因为旋钮和音色之间是线性关系，能直接解方程，不用一档一档试。</p><p>也正因为它只是个线性方程组，<strong>算起来极快</strong>——这正是它至今还被拿来当迭代初值的原因。</p></blockquote><p>三个用途：</p><ol><li><strong>矩估计</strong>：用样本 ρ̂ 代入解 φ̂。</li><li><strong>算 PACF</strong>：k 阶方程组的最后一个解就是 φₖₖ。</li><li><strong>判断平稳性</strong>：若解出的 φ 使特征根落在单位圆外，则非平稳。</li></ol><h2 id="_3-7-acf-pacf-理论特征总表" tabindex="-1">3.7 ACF/PACF 理论特征总表 <a class="header-anchor" href="#_3-7-acf-pacf-理论特征总表" aria-label="Permalink to &quot;3.7 ACF/PACF 理论特征总表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模型</th><th>ACF</th><th>PACF</th></tr></thead><tbody><tr><td>白噪声</td><td>全部为零</td><td>全部为零</td></tr><tr><td>AR(p)</td><td>拖尾（指数/振荡衰减）</td><td><strong>p 阶截尾</strong></td></tr><tr><td>MA(q)</td><td><strong>q 阶截尾</strong></td><td>拖尾</td></tr><tr><td>ARMA(p,q)</td><td>拖尾</td><td>拖尾</td></tr></tbody></table><p><img src="'+l+'" alt="ACF 与 PACF 的四种典型形态"></p><p>图 3-1　ACF 与 PACF 的四种典型形态（浅蓝带为 ±1.96/√n 的 95% 置信带）</p><p>★ <strong>这张图只能用于初步判断，不能用来定阶。</strong> 原因有三：样本 ACF 本身有抽样误差，&quot;截尾&quot;在图上很少干净利落；混合模型（ARMA）两者都拖尾，无法区分阶数；季节性和结构变化会污染 ACF 的形状。正确的用法是：用这张图给出<strong>初始候选</strong>，再用信息准则或样本外误差做<strong>最终选择</strong>。</p><blockquote><p><strong>打个比方</strong>：ACF/PACF 图就是<strong>指纹</strong>。指纹能认出&quot;这是 AR 还是 MA&quot;（型号对得上），却认不出&quot;具体是第几号&quot;（阶数）。指纹匹配只能缩小嫌疑人范围，最终定案还得靠信息准则和样本外检验这些&quot;证据&quot;。</p><p>顺带一句怎么记这张表：<strong>ACF 看&quot;总关系&quot;，PACF 看&quot;直接关系&quot;</strong>。MA 是有限块石头的余波，隔够远就彻底无关，所以总关系会断（ACF 截尾）；AR 是回声接力，隔多远都能间接传过去，所以总关系断不了（ACF 拖尾）。把这一条想通，表就不用背了。</p></blockquote><h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2><ol><li>MA 永远平稳，可逆性由 MA 根决定；AR 平稳性由 AR 根决定。</li><li>AR(p) 的 PACF 在 p 阶截尾，MA(q) 的 ACF 在 q 阶截尾，ARMA 两者都拖尾。</li><li>Green 函数 ψ(B) = θ(B)/φ(B)，是算方差、算预测、看冲击持续性的统一工具。</li><li>Yule-Walker 方程既用于矩估计，也用于算 PACF。</li><li>根接近单位圆时，数学上成立但统计上不可用，需要设阈值剔除。</li></ol><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：AR(p)、MA(q)、ARMA 的 ACF 和 PACF 各有什么特征？</strong></p><details class="details custom-block"><summary>点开看答案</summary><ul><li><strong>AR(p)</strong>：PACF 在 p 阶<strong>截尾</strong>，ACF 拖尾；</li><li><strong>MA(q)</strong>：ACF 在 q 阶<strong>截尾</strong>，PACF 拖尾；</li><li><strong>ARMA</strong>：ACF、PACF 都拖尾。</li></ul></details><p><strong>Q2：MA 模型一定平稳吗？AR 和 MA 的平稳性、可逆性分别由什么决定？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p><strong>MA 永远平稳</strong>（有限个白噪声的加权和）；MA 的<strong>可逆性</strong>由 MA 根决定。</p><p>AR 的<strong>平稳性</strong>由 AR 根决定。根接近单位圆时，数学上成立但统计上不可用，需要设阈值剔除。</p></details><p><strong>Q3：Green 函数 ψ(B) 是什么？它有什么用？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>ψ(B) = θ(B)/φ(B)，把 ARMA 写成 MA(∞) 形式：Xₜ = Σψⱼεₜ₋ⱼ。</p><p>它是<strong>统一工具</strong>：算方差、算预测误差、看一个冲击能持续多久，都靠这组 ψ 权重。</p></details>',73)])])}const c=o(e,[["render",a]]);export{d as __pageData,c as default};
